import json
sw = json.load(open('./swagger_degust.json'))

def resolve(ref):
    parts = ref.split('/')[1:]
    node = sw
    for p in parts: node = node[p]
    return node

def show(path):
    print('='*60)
    print(path)
    for method, spec in sw['paths'][path].items():
        print(f'  [{method}]', spec.get('summary',''))
        for prm in spec.get('parameters', []):
            print('    param:', prm.get('name'), prm.get('in'), prm.get('schema',{}).get('type'), 'required' if prm.get('required') else '')
        rb = spec.get('requestBody')
        if rb:
            for ct, c in rb.get('content', {}).items():
                sch = c.get('schema', {})
                if '$ref' in sch:
                    print('    body schema:', sch['$ref'])
                    node = resolve(sch['$ref'])
                    for k, v in node.get('properties', {}).items():
                        print('      ', k, v.get('type'), v.get('format',''))
        resp = spec.get('responses', {}).get('200', {})
        for ct, c in resp.get('content', {}).items():
            sch = c.get('schema', {})
            ref = sch.get('$ref') or sch.get('items',{}).get('$ref')
            if ref:
                print('    200 schema:', ref, '(array)' if sch.get('type')=='array' else '')
                node = resolve(ref)
                for k, v in node.get('properties', {}).items():
                    t = v.get('type') or v.get('$ref','')
